// ============================================================================
// MODULE: ov5640_dvp_Y8_capture
// DESCRIPTION: Receives an OV5640 parallel YUV422 (YUYV) stream and stores
// the luminance (Y8) of each pixel.
//
// Camera signals:
// - cam_pclk: pixel/byte clock generated by camera
// - cam_vsync: frame synchronization
// - cam_href: high while valid bytes of a line are transmitted
// - cam_data: 8-bit parallel data
//
// YUV422 uses two camera-clock cycles per pixel: (Y0,U) (Y1,V) ...
// The first byte of each pair is the pixel luminance Y and is written to the
// double framebuffer; the second byte (U or V) is discarded.
//
// Each frame is either completely saved or completely discarded.
// wr_allow is sampled only at the beginning of the frame.
// ============================================================================


module ov5640_dvp_Y8_capture #(
    parameter int IMG_W      = 160,
    parameter int IMG_H      = 120,
    parameter int FRAME_PIX  = IMG_W * IMG_H,
    parameter int ADDR_BITS  = $clog2(FRAME_PIX),

    parameter bit VSYNC_ACTIVE = 1'b1,  //Specifies which cam_vsync level should be considered active
    parameter bit HREF_ACTIVE  = 1'b1   //Specifies which cam_href level should be considered active
)(
    input  logic rst_n,
    input  logic capture_ready,    //high when the camera configuration is completed

    input  logic       cam_pclk,
    input  logic       cam_vsync,
    input  logic       cam_href,
    input  logic [7:0] cam_data,

    input  logic wr_allow,   //used to not overwrite the frame that HDMI is reading ( 1: save frame; 0: discard frame )

    output logic pix_valid,  //high when the pixel is converted and ready to be saved in frambuffer
    output logic [ADDR_BITS-1:0] pix_addr,
    output logic [7:0] pix_data,
    output logic frame_done  //high after the arrival of FRAME_PIX pixels
);

    logic vsync_is_active;
    logic href_is_active;

    assign vsync_is_active = (cam_vsync == VSYNC_ACTIVE);
    assign href_is_active  = (cam_href  == HREF_ACTIVE);

//    logic vsync_d;     //VSYNC value from the previous cycle

    logic frame_active;    //0: No frames currently being captured: 1: frame in capture
    logic capture_enable;  //useful for preventing wr_allow change while saving

    // 0: waiting for first byte of the pair (Y)
    // 1: waiting for second byte of the pair (U or V, discarded)
    logic byte_phase;

    logic [7:0] first_byte;  // first byte of the pair = luminance Y

    localparam int PIX_CNT_BITS = $clog2(FRAME_PIX + 1);    //If FRAME_PIX is a power of 2, the counter would not be able to represent FRAME_PIX itself
    logic [PIX_CNT_BITS-1:0] pixel_count;


    // =========================================================================
    // DVP receiver
    // =========================================================================

    always_ff @(posedge cam_pclk or negedge rst_n) begin
        if (!rst_n) begin
//            vsync_d       <= 1'b0;

            frame_active  <= 1'b0;
            capture_enable <= 1'b0;

            byte_phase    <= 1'b0;
            first_byte    <= 8'd0;
            pixel_count   <= '0;

            pix_valid     <= 1'b0;
            pix_addr      <= '0;
            pix_data      <= 8'd0;
            frame_done    <= 1'b0;
        end
        else begin
            pix_valid  <= 1'b0;
            frame_done <= 1'b0;

//            vsync_d <= vsync_is_active;

            // =================================================================
            // Camera not initialized yet
            // =================================================================

            if (!capture_ready) begin
                frame_active   <= 1'b0;
                capture_enable <= 1'b0;
                byte_phase     <= 1'b0;
                pixel_count    <= '0;
            end

            // =================================================================
            // VSYNC active: frame boundary/blanking. 
            // We use VSYNC to indicate that the record of new frame is starting
            // =================================================================

            else if (vsync_is_active) begin
            
//                if (!vsync_d && frame_active) begin  // if VSYNC has just become active and we had a frame being captured...
// //                  Signal completion only if exactly FRAME_PIX pixels
// //                  were captured and this frame was enabled.
//                    if (capture_enable && (pixel_count == FRAME_PIX)) begin
//                        frame_done <= 1'b1;
//                    end
//                end

                frame_active   <= 1'b0;
                capture_enable <= 1'b0;

                byte_phase  <= 1'b0;
                pixel_count <= '0;
            end

            // =================================================================
            // Active frame area
            // =================================================================

            else begin

                // First non-VSYNC clock starts a new frame.
                // The first time HREF becomes active after VSYNC:
                // -> the frame is considered to have started;
                // -> wr_allow is sampled;
                // -> the counter resets to zero;
                // -> the module aligns to the first byte of the pair (Y).
                if (!frame_active && href_is_active) begin
                    frame_active   <= 1'b1;
                    capture_enable <= wr_allow;

                    byte_phase  <= 1'b0;
                    pixel_count <= '0;
                end

                // Reset byte alignment at every line boundary.
                if (!href_is_active) begin
                    byte_phase <= 1'b0;
                end

                // Receive YUV422 bytes only while HREF is active.
                else begin
                    if (!byte_phase) begin
                        first_byte <= cam_data;
                        byte_phase <= 1'b1;
                    end
                    else begin
                        byte_phase <= 1'b0;

                        // One complete pixel pair is now available:
                        // first_byte = Y (stored), cam_data = U or V (discarded)
                        if (capture_enable &&
                            (pixel_count < FRAME_PIX)) begin
                            pix_valid <= 1'b1;
                            pix_addr  <= pixel_count[ADDR_BITS-1:0];
                            pix_data  <= first_byte;    // Y (luminance) of this pixel

                            if (pixel_count == FRAME_PIX - 1) begin
                                frame_done <= 1'b1;
                            end
                        end

                        if (pixel_count < FRAME_PIX) begin
                            pixel_count <= pixel_count + 1'b1;
                        end
                    end
                end
            end
        end
    end

endmodule